package com.eventhub.service;
import com.eventhub.dto.TicketResponse;import com.eventhub.entity.Ticket;import com.eventhub.repository.TicketRepository;import com.eventhub.util.TicketSecurity;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.io.*;import java.util.Base64;import com.google.zxing.*;import com.google.zxing.client.j2se.MatrixToImageWriter;import com.google.zxing.common.BitMatrix;import com.google.zxing.qrcode.QRCodeWriter;
@Service @RequiredArgsConstructor public class TicketService{private final TicketRepository tickets;@Value("${app.jwt.secret}") private String ticketSecret;@Transactional(readOnly=true) public TicketResponse get(String email,String ticketId){Ticket t=tickets.findByTicketId(ticketId).orElseThrow(()->new IllegalArgumentException("Ticket not found"));if(!t.getRegistration().getUser().getEmail().equalsIgnoreCase(email))throw new org.springframework.security.access.AccessDeniedException("Not your ticket");String sig=TicketSecurity.hmac(t.getTicketId(),ticketSecret);String payload="EVENTHUB:TICKET:"+t.getTicketId()+":"+sig;return TicketResponse.of(t,qrPng(payload));}private String qrPng(String payload){try{BitMatrix matrix=new QRCodeWriter().encode(payload,BarcodeFormat.QR_CODE,320,320);ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(matrix,"PNG",out);return "data:image/png;base64,"+Base64.getEncoder().encodeToString(out.toByteArray());}catch(Exception e){throw new IllegalStateException("Unable to generate ticket QR",e);}}}
